/**
 * 预览页：把 [KyrgyzKeyboardEngine] 挂接到一段本地文本状态，
 * 让用户在 App 内即可试打，验证 34 个字母/RTL/切换布局等能力。
 *
 * 该页不依赖 InputMethodService，因此可离线预览。
 */
@Composable
fun PreviewScreen() {
    var buffer by remember { mutableStateOf("") }
    var layoutVersion by remember { mutableStateOf(0) }

    val engine = remember {
        KyrgyzKeyboardEngine(object : KyrgyzKeyboardEngine.Listener {
            override fun onCommitCandidate(text: String) { buffer += text }
            override fun onComposingChanged(composing: String) {}
            override fun onKeyPress(code: String) {
                buffer += code
            }

            override fun onKeyAction(action: FunctionType) {
                when (action) {
                    FunctionType.SPACE -> buffer += " "
                    FunctionType.NEWLINE -> buffer += "\n"
                    FunctionType.BACKSPACE -> if (buffer.isNotEmpty()) {
                        buffer = buffer.dropLast(1)
                    }
                    FunctionType.SWITCH_LAYOUT -> layoutVersion++
                    FunctionType.DONE, FunctionType.SHIFT, FunctionType.SWITCH_LANGUAGE -> Unit
                }
            }
        })
    }
    val rows = remember(layoutVersion) { engine.getRows() }

    Column(modifier = Modifier.fillMaxSize()) {
        // 预览区
        Surface(
            color = MaterialTheme.colorScheme.surfaceVariant,
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
                .padding(16.dp)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = stringResource(id = R.string.preview_label),
                    style = MaterialTheme.typography.labelLarge
                )
                Text(
                    text = if (buffer.isEmpty())
                        stringResource(id = R.string.preview_placeholder)
                    else buffer,
                    style = MaterialTheme.typography.headlineSmall,
                    modifier = Modifier.fillMaxWidth()
                )
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    TextButton(onClick = { buffer = "" }) {
                        Text(text = stringResource(id = R.string.preview_clear))
                    }
                }
            }
        }
        // 键盘区
        CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
            Surface(
                color = MaterialTheme.colorScheme.surface,
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(4.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    rows.forEach { row ->
                        KeyboardRowView(row) { key ->
                            engine.handleKey(key)
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun KeyboardRowView(row: KeyboardRow, onKey: (KyrgyzKey) -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(48.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        row.keys.forEach { key ->
            KeyView(
                key = key,
                modifier = Modifier.weight(key.weight),
                onClick = { onKey(key) },
                onLongClick = { key.variants.firstOrNull()?.let { onKey(KyrgyzKey.letter(it)) } }
            )
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun KeyView(
    key: KyrgyzKey,
    modifier: Modifier = Modifier,
    onClick: () -> Unit,
    onLongClick: () -> Unit
) {
    val bg = when (key.type) {
        KeyType.FUNCTION -> MaterialTheme.colorScheme.secondaryContainer
        KeyType.SYMBOL -> MaterialTheme.colorScheme.surfaceVariant
        KeyType.LETTER -> MaterialTheme.colorScheme.primaryContainer
    }
    val fg = when (key.type) {
        KeyType.FUNCTION -> MaterialTheme.colorScheme.onSecondaryContainer
        KeyType.SYMBOL -> MaterialTheme.colorScheme.onSurfaceVariant
        KeyType.LETTER -> MaterialTheme.colorScheme.onPrimaryContainer
    }
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(8.dp))
            .background(bg)
            .combinedClickable(onClick = onClick, onLongClick = onLongClick),
        contentAlignment = Alignment.Center
    ) {
        Text(text = key.label, color = fg, fontSize = 18.sp, textAlign = TextAlign.Center)
    }
}